/* Learning Data: IA y arquitectura continua. Los textos de los labs (Desarma) y las situaciones (Tú decides) de la serie, en
   español (Latinoamérica). Mantén las claves iguales a learn.en.js: los mismos labs, en el mismo orden, con los mismos ids, tipos,
   películas, capítulos y colores, las mismas tarjetas en el mismo orden, y las mismas situaciones con sus números y cada respuesta
   correcta en el mismo lugar. Las palabras siguen los subtítulos en español de las películas: informar, redactar, verificar,
   ejecutar; un gestor de facturación, quien dirige comercialización, la puerta de enlace, el lugar propio del chat, público,
   interno, confidencial, restringido, el muro, comprobaciones, recorrido, lo que está en marcha.
   build_series.py (series_learn) lee las primeras claves de cada lab y de cada situación, en el mismo orden que en inglés. */
window.ACA={lang:"es",films:6,
ui:{lab:"Lab",of:"de",coming:"Película en camino",comingNote:"Esta película se está haciendo. El lab ya está listo.",watch:"Ver el capítulo",
  next:"Siguiente:",makeCall:"Tú decides →",inPractice:"En la práctica",labsLabel:"Los labs",again:"Empezar de nuevo",go:"Siguiente",seeAll:"Ver el cuadro completo",
  right:"Correcto.",notQuite:"No del todo.",belongs:"La respuesta: {b}.",placed:"{n} de {of} ubicadas",firstTry:"correctas al primer intento",card:"Tarjeta {n} de {of}",
  scenario:"Situación",qsLabel:"Las situaciones",score:"Puntaje",answered:"respondidas",toGo:"por responder",good:"Bien pensado.",explore:"Explora el lab:",
  results:"Ver cómo te fue",nextQ:"Siguiente situación →",allFilms:"Todas las películas",filter:"Mostrar las situaciones de",stillOpen:"{n} siguen abiertas",filmN:"Película {n} de {of}"},
labs:[
/* ---------- 1 · Los agentes en el mapa ---------- */
{id:"far",kind:"sort",film:1,chapter:"far",c:"#82e6d7",name:"Hasta dónde, tarea por tarea",
 idea:"Un agente nunca recibe una actividad entera. En cada tarea, el responsable de su proceso fija hasta dónde llega: informar a una persona, redactar para ella, verificar su trabajo o ejecutar la tarea solo. Algunas tareas no las toca.",
 points:["<b>Tarea por tarea, lo fija el responsable del proceso.</b> Ayudar a los hogares que no pueden pagar es de quien dirige comercialización, así que fija cada paso del chat.",
  "<b>Una decisión bajo reglas se queda con una persona.</b> Acordar un plan es de un gestor de facturación, según las reglas del regulador: el chat puede redactar la solicitud, nunca acordarla.",
  "<b>Alguien responde por él.</b> El responsable que fija sus pasos responde por el trabajo del agente, como por cualquiera de ese equipo. El agente nunca aprueba."],
 real:"Siéntate con el responsable de un proceso y recórrelo tarea por tarea. En cada una, pregunta qué pasa si el agente se equivoca, y quién lo notaría. Escribe el paso junto a la tarea, con la persona a la que deriva.",
 w:{prompt:"Diez tareas para los agentes de la empresa. En cada una, ¿hasta dónde puede llegar el agente?",
  buckets:[["inform","informar"],["draft","redactar"],["verify","verificar"],["run","ejecutar solo"],["none","nada: decide una persona"]],
  items:[
   {t:"Responder la pregunta de un hogar sobre su factura",s:"responder sobre una factura",b:"run",why:"La respuesta está en la propia factura del hogar, y darla no cambia nada. Quien dirige comercialización deja que el chat lo haga solo."},
   {t:"Acordar un plan de pagos con un hogar que no puede pagar",s:"acordar un plan de pagos",b:"none",why:"Acordar un plan lo decide un gestor de facturación, según las reglas del regulador para los hogares que no pueden pagar. El chat llegó a acordar 212 antes de que nadie lo notara."},
   {t:"Recibir el pedido de un hogar de más plazo para pagar",s:"recibir un pedido de plazo",b:"draft",why:"El chat escribe la solicitud para un gestor de facturación, y le dice al hogar cuándo tendrá respuesta. El gestor decide."},
   {t:"Comprobar que el plan de un gestor cumple las reglas para hogares en dificultades",s:"comprobar un plan",b:"verify",why:"El agente comprueba el trabajo de una persona contra las reglas, y dice lo que encuentra. El gestor sigue decidiendo."},
   {t:"Decirle al gestor cuánto debe el hogar, y cuánto ha pagado",s:"decir cuánto se debe",b:"inform",why:"Datos para la persona que decide: el agente informa, y no decide nada."},
   {t:"Redactar los turnos de las cuadrillas de la semana",s:"redactar los turnos",b:"draft",why:"El planificador de cuadrillas los redacta, un supervisor los aprueba, y Grace responde por él."},
   {t:"Responder una pregunta sobre los precios de este año",s:"responder sobre precios",b:"run",why:"La respuesta sale de las tarifas oficiales, iguales para todos, y no cambia nada. El chat puede responder solo."},
   {t:"Quitarle a un hogar el recargo por atraso",s:"quitar un recargo",b:"none",why:"Quitar un recargo es una decisión de facturación. La toma una persona, como cuando facturación devolvió los recargos de los 212 planes."},
   {t:"Comprobar un turno que un supervisor escribió a mano contra las horas de descanso de las cuadrillas",s:"comprobar el descanso",b:"verify",why:"El agente comprueba el trabajo de una persona contra las reglas de descanso, y dice qué las rompe. El supervisor decide qué cambiar."},
   {t:"Avisarle a un gestor que un hogar no hizo un pago de su plan",s:"avisar de un pago perdido",b:"inform",why:"El agente le dice al gestor lo que pasó. Qué hacer al respecto lo decide el gestor."}],
  end:"{n} de {of} al primer intento. Cada tarea tiene su paso, fijado por el responsable de su proceso, y toda decisión bajo reglas se queda con una persona. En el mapa, junto a sus tareas, cada agente tiene también su propio rol, su propia identidad, una derivación y alguien que responde por él.",
  pic:{title:"el paso de cada tarea",sub:"cada paso, fijado por el responsable del proceso de la tarea",done:"Cada paso lo fija su responsable, que responde por el agente.",
   alt:"Los cuatro pasos que un agente puede dar en una tarea, de informar a ejecutar, y las decisiones que se quedan con una persona, con cada tarea en su paso."}}},
/* ---------- 2 · La plataforma de IA ---------- */
{id:"platform",kind:"sort",film:2,chapter:"test",c:"#a0e08c",name:"Compartido, o propio",
 idea:"Debajo de cada agente hay lo mismo: un modelo para responder, herramientas, memoria y búsqueda. Hechos una vez, son de la plataforma. Para qué sirve cada agente sigue siendo suyo. Ordena lo que usan los seis agentes, y encuentra lo que ya no tiene lugar.",
 points:["<b>La prueba:</b> un propósito, con su lógica incorporada, es una aplicación. Capacidades compartidas, donde muchos responsables hacen lo suyo, son una plataforma.",
  "<b>Una sola puerta a cada modelo.</b> Cada llamada pasa por la puerta de enlace, con la identidad propia del agente, anotada, dentro de sus límites, y solo a modelos con los que la empresa tiene condiciones.",
  "<b>Compartida, y con responsable.</b> El equipo de Ravi opera la plataforma. El responsable de cada agente responde por lo que hace, y acepta antes de que pase a otro modelo."],
 real:"Haz una lista de lo que alcanza cada uno de tus agentes, y cómo: qué modelo, qué clave, qué herramientas. Lo que dos agentes alcanzan cada uno a su manera va en la plataforma. Una llamada que nadie encuentra en un registro es lo primero que hay que arreglar.",
 w:{prompt:"Doce cosas que usan los agentes. ¿Cada una es de la plataforma, propia del agente, o algo que ya no tiene lugar?",
  buckets:[["platform","de la plataforma: compartido"],["own","propio del agente"],["gone","ya no tiene lugar"]],
  items:[
   {t:"Un modelo que escribe las respuestas de los agentes",s:"un modelo",b:"platform",why:"Un modelo no sirve a un solo propósito: el chat y el planificador de cuadrillas podrían usar el mismo. Cada agente llega a él por la puerta de enlace de la plataforma."},
   {t:"Las instrucciones del planificador de cuadrillas: cómo redacta los turnos de cada semana",s:"las instrucciones del planificador",b:"own",why:"Para qué sirve un agente, y cómo lo hace, es suyo: una aplicación, con un responsable que responde por ella. Grace, en el caso del planificador."},
   {t:"Una clave de un proveedor, guardada en el script del planificador de cuadrillas",s:"una clave en un script",b:"gone",why:"Con esa clave, un modelo retirado paró los turnos un lunes. Ahora cada llamada pasa por la puerta de enlace, con la identidad propia del agente."},
   {t:"La búsqueda en los documentos de la empresa",s:"la búsqueda",b:"platform",why:"Encontrar la página justa le sirve a cada agente que la necesite. Hecha una vez, es de la plataforma."},
   {t:"La memoria: lo que un agente guarda de un paso al siguiente",s:"la memoria",b:"platform",why:"Todos los agentes la necesitan, y ninguno necesita una propia: es una capacidad compartida, así que es de la plataforma."},
   {t:"La lógica del chat para saber cuándo pasar un hogar a una persona",s:"la derivación del chat",b:"own",why:"La lógica de las tareas de un agente es parte de para qué sirve. Sigue siendo propia del chat, y quien dirige comercialización responde por ella."},
   {t:"Los límites que evitan que un agente atascado en un bucle dispare la cuenta",s:"límites a cada agente",b:"platform",why:"La puerta de enlace mantiene a cada agente dentro de sus límites, para que ninguno dispare la cuenta ni desplace al resto. Los fija el equipo de Ravi."},
   {t:"Un modelo con el que la empresa no tiene condiciones",s:"un modelo sin condiciones",b:"gone",why:"La puerta de enlace solo llega a modelos con los que la empresa tiene condiciones: dónde se guardan sus datos, y que no se usen para entrenar el modelo de nadie."},
   {t:"Los controles con los que se prueban los resultados del planificador de cuadrillas",s:"los controles del planificador",b:"own",why:"Cada agente tiene sus propios controles. Un modelo de reemplazo se prueba con ellos, y el responsable del agente revisa los resultados antes de pasar."},
   {t:"Herramientas que le permiten a un agente consultar algo, o hacer algo",s:"herramientas",b:"platform",why:"Las herramientas son capacidades compartidas, ofrecidas a cada agente, así que son de la plataforma."},
   {t:"Para qué sirve el chat: responder a los hogares sobre facturas, precios y trabajos programados",s:"el propósito del chat",b:"own",why:"Su propósito es suyo. Eso es lo que lo hace una aplicación, con alguien que responde por ella."},
   {t:"El chat llegando al modelo de su proveedor por un camino propio, por fuera de la puerta de enlace",s:"un camino por fuera",b:"gone",why:"Ahora hasta el chat del proveedor llega a su modelo por la puerta de enlace, así que cada llamada queda anotada: qué agente, qué modelo, cuándo y cuánto costó."}],
  end:"{n} de {of} al primer intento. La plataforma tiene lo que no sirve a un solo propósito: los modelos, las herramientas, la memoria, la búsqueda, y la puerta de enlace ante cada modelo. Cada agente conserva su propósito, sus instrucciones y su lógica, y su responsable responde por él.",
  pic:{title:"seis agentes, una plataforma",sub:"lo compartido, y lo que conserva cada uno",done:"Una plataforma bajo cada agente; cada uno conserva su propósito.",
   rows:{platform:"de la plataforma: compartido",own:"propio de cada agente",gone:"ya no tiene lugar"},
   alt:"Lo propio de los agentes, lo compartido de la plataforma, y lo que ya no tiene lugar, tachado, con cada cosa en su fila."}}},
/* ---------- 3 · Qué puede leer un agente ---------- */
{id:"place",kind:"sort",film:3,chapter:"level",c:"#84e2a0",name:"Llena el lugar del chat",
 idea:"El chat responde al público, así que lee los productos oficiales, y solo lo que le toca leer. Inés le da un lugar propio. Para cada cosa que podría leer, decide si va en ese lugar, le llega al chat de otra forma, o nunca le llega.",
 points:["<b>Un lugar propio,</b> que solo tiene lo que el chat puede leer, y al que llega con su propia identidad. Lo que no puede leer ni siquiera está ahí: no hay máscara que una regla equivocada deje pasar.",
  "<b>Decide el nivel de cada producto.</b> Los productos públicos e internos van en su lugar. La cuenta de un hogar es confidencial: se lee solo cuando su titular inicia sesión. Los datos restringidos, como las necesidades médicas, nunca.",
  "<b>Preguntar, no leer.</b> Donde el chat necesita una decisión que depende de datos restringidos, una pequeña herramienta responde sí o no, y nunca el porqué."],
 real:"Para un agente que conozcas, haz una lista de lo que lee hoy, y de dónde viene cada cosa. Lo que lee de una exportación o de una copia, o lo que solo una máscara o una instrucción le impide leer, es lo primero que hay que arreglar.",
 w:{prompt:"Diez cosas que el chat podría leer. ¿Dónde va cada una?",
  buckets:[["place","en su lugar propio"],["signin","cuando su titular inicia sesión"],["tool","el sí o no de una pequeña herramienta"],["never","nunca a su alcance"]],
  items:[
   {t:"Las tarifas de este año",s:"tarifas",b:"place",why:"Un producto oficial, público, al día por su contrato. Cuando cambian los precios, la respuesta del chat cambia ese mismo día."},
   {t:"La cuenta de un hogar: sus facturas y sus pagos",s:"una cuenta",b:"signin",why:"Una cuenta es confidencial. El chat lee una solo cuando su titular inicia sesión, como hace el sitio web: la suya, y la de nadie más."},
   {t:"Las notas del centro de contacto",s:"las notas del centro de contacto",b:"never",why:"Ahí se anotan las necesidades médicas de las personas. La primera versión del chat las leía, y las necesidades de una familia llegaron a un extraño."},
   {t:"Los trabajos programados, por calle",s:"trabajos programados",b:"place",why:"El equipo de Grace los lleva como un producto, con un contrato, y Grace acepta en el ticket que el chat pueda leerlos."},
   {t:"Los precios del año pasado, exportados a una carpeta compartida",s:"una exportación de precios",b:"never",why:"Una copia de una copia que nadie actualizaba: un hogar planeó su invierno con un precio que ya había cambiado."},
   {t:"Si pasar ya a una persona a este hogar que inició sesión",s:"¿pasarlo a una persona?",b:"tool",why:"El equipo que lleva la lista ofrece una pequeña herramienta que responde sí o no. Nunca el porqué: la persona que devuelve la llamada ve el porqué."},
   {t:"Las páginas de ayuda",s:"páginas de ayuda",b:"place",why:"Son públicas, y las lleva su propio equipo. En Databricks, son un índice de búsqueda que el chat puede leer."},
   {t:"Los términos del glosario, como «titular de la cuenta»",s:"los términos del glosario",b:"place",why:"Vienen con los productos, así que una palabra significa para el chat lo mismo que para la empresa."},
   {t:"La lista de hogares que necesitan luz para equipos médicos, tras una máscara",s:"necesidades médicas, enmascaradas",b:"never",why:"Una máscara deja los datos restringidos al alcance, y una regla equivocada los deja pasar. Lo que el chat no puede leer ni siquiera está en su lugar."},
   {t:"La cuenta de un vecino por la que pregunta quien llama",s:"la cuenta de un vecino",b:"never",why:"El chat lee una cuenta solo cuando su titular inicia sesión. Nadie sabe de otro hogar que no sea el suyo."}],
  end:"{n} de {of} al primer intento. El lugar del chat tiene los productos oficiales y sus términos: nada restringido, y ninguna copia. Una cuenta se lee solo cuando su titular inicia sesión, y lo único que el chat necesita saber de las necesidades médicas le llega como un sí o un no.",
  pic:{title:"lo que el chat puede leer",sub:"un lugar propio, con su propia identidad",done:"Solo lo que puede leer: ninguna copia, y nada restringido.",
   rows:{place:"en su lugar propio",signin:"cuando su titular inicia sesión",tool:"el sí o no de una herramienta",never:"nunca a su alcance"},
   alt:"El lugar propio del chat, la cuenta de un hogar cuando su titular inicia sesión, el sí o no de una pequeña herramienta, y lo que el chat nunca alcanza, con cada cosa en su fila."}}},
/* ---------- 4 · Un primer borrador, no una página en blanco ---------- */
{id:"confirm",kind:"sort",film:4,chapter:"confirm",c:"#ffd166",name:"Redactar, preguntar, confirmar",
 idea:"El agente del mapa redacta; Tomás pregunta qué falta y qué está mal; el responsable de cada elemento confirma su propia parte. Ordena quién hace qué mientras el diseño de la batería pasa de un primer borrador al modelo.",
 points:["<b>Un borrador al que reaccionar.</b> Desde los modelos de referencia de la industria y los documentos propios de la empresa, cada elemento con su fuente, y las suposiciones del agente marcadas como tales.",
  "<b>Pregunta qué falta y qué está mal,</b> no si está bien: la gente tiende a aprobar sin mirar todo lo que parece seguro.",
  "<b>Solo los responsables confirman.</b> Cada elemento nombra a su responsable, que lo confirma con su nombre y la fecha. Lo que un responsable corrige, el agente lo vuelve a redactar, y nunca confirma."],
 real:"Cuando empiece un diseño, pide un primer borrador con cada fuente a la vista, y dale a cada responsable solo su parte para revisar. En la revisión, pregunta qué falta y qué está mal, y guarda quién confirmó qué, y cuándo.",
 w:{prompt:"Once pasos en el camino del primer borrador de la batería al modelo. ¿Quién hace cada uno?",
  buckets:[["agent","el agente del mapa"],["tomas","Tomás, el arquitecto"],["owner","el responsable del elemento"]],
  items:[
   {t:"Leer el CIM, la lista de la IEC y el modelo europeo de roles del mercado",s:"leer los modelos de referencia",b:"agent",why:"El agente lee los modelos de referencia de la industria, y los documentos propios de la empresa, para el primer borrador."},
   {t:"Preguntar a los responsables qué falta, y qué está mal",s:"preguntar qué falta",b:"tomas",why:"No si está bien: un borrador prolijo parece seguro, y la gente tiende a aprobarlo sin mirar."},
   {t:"Confirmar un elemento, con un nombre y la fecha",s:"confirmar un elemento",b:"owner",why:"Solo su responsable lo confirma: Grace los de la red, quien dirige comercialización los suyos, Ama las reglas."},
   {t:"Redactar cincuenta y ocho elementos en dos días",s:"redactar 58 elementos",b:"agent",why:"Las capacidades, un flujo de valor del alta al crédito, los procesos y su información: cada uno un borrador hasta que su responsable lo confirme."},
   {t:"Encontrar un paso que llevaría información de clientes al otro lado del muro",s:"encontrar lo que está mal",b:"owner",why:"Lo encontró Ama: el borrador hacía que comercialización usara la lista de la red de casas con paneles solares. Cada fuente tenía razón por sí sola; el paso que las unió, no."},
   {t:"Marcar como suposición quién decide cuándo se carga la batería",s:"marcar una suposición",b:"agent",why:"Donde ninguna fuente lo dice, el borrador lo dice. El agente marca su propia suposición, para que la resuelva el responsable."},
   {t:"Agregar el paso que apaga la batería antes de que trabajen las cuadrillas",s:"agregar lo que falta",b:"owner",why:"Grace encontró lo que ningún documento decía: una batería en la calle es una fuente nueva, y toda fuente se apaga y se bloquea antes de que una cuadrilla trabaje en una línea."},
   {t:"Pedirle al agente del mapa un primer borrador antes de los talleres",s:"pedir un borrador",b:"tomas",why:"La gente responde mejor a una propuesta que a una pregunta abierta, así que los talleres empiezan desde el borrador."},
   {t:"Volver a redactar un elemento corregido, para que lo confirme su responsable",s:"redactar una corrección",b:"agent",why:"Lo que un responsable corrige, el agente lo vuelve a redactar. Sigue sin confirmarlo."},
   {t:"Tachar un elemento, para que salga del mapa",s:"tachar uno",b:"owner",why:"Lo que un responsable tacha sale del mapa. Así salieron ocho elementos."},
   {t:"Llevar el mapa, con la fuente y el responsable de cada elemento",s:"llevar el mapa",b:"tomas",why:"Tomás lleva el mapa y dirige la revisión. No confirma la parte de otro equipo."}],
  end:"{n} de {of} al primer intento. El agente leyó y redactó; Tomás preguntó y llevó el mapa; los responsables encontraron lo que estaba mal y lo que faltaba, y confirmaron su propia parte. En cinco semanas, 41 elementos como se redactaron, 9 corregidos, 8 tachados y 4 agregados.",
  pic:{title:"el diseño de la batería",sub:"58 elementos, cada uno un borrador hasta que su responsable lo confirme",done:"41 como se redactaron · 9 corregidos · 8 tachados · 4 agregados",
   alt:"Tres filas, para el agente del mapa, para Tomás y para el responsable de cada elemento, con cada paso en la fila de quien lo hace."}}},
/* ---------- 5 · Cada cambio, comprobado ---------- */
{id:"checks",kind:"sort",film:5,chapter:"checks",c:"#eea470",name:"Corre las comprobaciones del mapa",
 idea:"Como un ladrillo estampado, cada elemento del mapa dice quién es su responsable y de dónde viene, así que el mapa puede probarse en cada cambio. Pasa los cambios de este mes por sus comprobaciones: ¿cuál para a cada uno, y cuáles pasan?",
 points:["<b>Comprobaciones en cada cambio:</b> cada elemento tiene un responsable y una fuente; cada capacidad la realiza un proceso o un sistema; cada objeto de datos representa un objeto de negocio; ningún elemento queda sin enlazar, y ninguno está dos veces.",
  "<b>Cada regla tiene un lugar propio, y un caso que debe fallar.</b> Una comprobación que nunca falló puede no comprobar nada.",
  "<b>Un cambio que falla espera,</b> hasta corregirse o hasta que su responsable diga por qué. En software, comprobaciones así se llaman funciones de aptitud."],
 real:"Elige una regla que tu arquitectura debe cumplir, y escribe el cambio que la rompería. Corre tus comprobaciones con ese cambio: si nada lo para, la comprobación no comprobaba nada.",
 w:{prompt:"Diez cambios al mapa. ¿Qué comprobación para a cada uno, o pasa?",
  buckets:[["source","un responsable y una fuente"],["realised","la realiza un proceso o sistema"],["stands","representa un objeto de negocio"],["linked","sin enlazar, o dos veces"],["rule","la comprobación de una regla"],["pass","pasa"]],
  items:[
   {t:"Agregar un servicio de SMS, todavía sin responsable",s:"un servicio de SMS",b:"source",why:"Cada elemento tiene un responsable y una fuente. Las comprobaciones paran ahí hasta que lo asume quien dirige comercialización."},
   {t:"La red avisa a cada comercializadora, en iguales condiciones, qué hogares pierden la luz y cuándo",s:"avisar a cada comercializadora",b:"pass",why:"El trabajo programado es de la red, y la red trata igual a todas las comercializadoras. La regla del muro se cumple."},
   {t:"Agregar la capacidad «avisar a los hogares antes de un trabajo programado», sin nada que todavía la haga",s:"una capacidad sola",b:"realised",why:"Una capacidad que nada realiza es solo un deseo en el mapa. Cada capacidad la realiza un proceso o un sistema."},
   {t:"Enviar a comercialización la lista de la red de hogares con paneles solares",s:"la lista solar a comercialización",b:"rule",why:"La información de los clientes se queda donde se recogió. Este es justo el caso que debe fallar, y falla."},
   {t:"Agregar un objeto de datos, «teléfonos (copia)», que no representa nada del negocio",s:"una copia de los teléfonos",b:"stands",why:"Cada objeto de datos representa un objeto de negocio. Enlazada al contacto del cliente, y con un responsable, la copia del centro de contacto entró en el mapa."},
   {t:"Dibujar una segunda tabla de «trabajo programado» junto a la primera",s:"una segunda tabla",b:"linked",why:"Ninguno está dos veces. Con dos tablas para una sola cosa, las cartas siguieron leyendo la antigua, y 1,900 hogares se quedaron sin luz sin aviso."},
   {t:"Cada comercializadora escribe a sus propios clientes, desde sus propios contactos",s:"cada una escribe a los suyos",b:"pass",why:"Los teléfonos son de comercialización: cada comercializadora guarda los de sus clientes. Nada cruza el muro."},
   {t:"Copiar un elemento del diagrama de un proveedor, sin anotar su fuente",s:"un elemento sin fuente",b:"source",why:"Cada elemento dice de dónde viene, para que su responsable pueda comprobarlo contra eso."},
   {t:"Agregar un proceso que no se enlaza con ninguna capacidad, información ni sistema",s:"un proceso solo",b:"linked",why:"Ningún elemento queda sin enlazar. Un proceso sin enlaces no se puede recorrer, así que ningún cambio lo encontraría."},
   {t:"Darle al servicio de SMS su responsable, quien dirige comercialización, y su fuente",s:"el servicio, con responsable",b:"pass",why:"Una vez que lo asume quien dirige comercialización, con su fuente, las comprobaciones pasan, y el recorrido sigue."}],
  end:"{n} de {of} al primer intento. Siete cambios esperan hasta corregirse, o hasta que sus responsables digan por qué; tres siguen adelante. Y el caso que debe fallar falló: enviar a comercialización la lista de la red de hogares con paneles solares se para cada vez.",
  pic:{title:"cada cambio, comprobado",sub:"cada elemento, estampado con su responsable y su fuente",done:"Siete esperan hasta corregirse · tres siguen adelante",
   alt:"Las comprobaciones del mapa, una fila cada una, y una fila para lo que pasa, con cada cambio en la comprobación que lo para, o en pasa."}}}
],
qs:[
{type:"choice",n:11,lab:"far",film:1,title:"Su propio inicio de sesión",vis:{k:"role",own:1},
 sit:"Los analistas de planificación de la red crean un agente que redacta pronósticos de carga. Para ahorrar una semana, quieren que trabaje con el inicio de sesión de un analista, que ya tiene todos los permisos que necesita.",
 opts:[{t:"Darle una identidad propia, una por cada conjunto de permisos que necesita, para que cada registro diga qué agente hizo qué.",ok:true},
  {t:"Usar el inicio de sesión del analista, y anotar en las instrucciones del agente qué permisos de esos no debe tocar.",why:"Una instrucción no es un límite: tendría todos los permisos del analista, y su trabajo parecería el de esa persona."},
  {t:"Usar el inicio de sesión del analista hasta que el agente demuestre lo que vale, y luego pasarlo a una identidad propia.",why:"Mientras tanto, nadie podría distinguir su trabajo del trabajo del analista, ni detenerlo sin detener también a esa persona."}],
 why:"Un agente trabaja con su propia identidad, nunca la de una persona: una por cada conjunto de permisos que necesita. Así, cada registro dice qué agente hizo qué, y se lo puede detener por separado."},
{type:"choice",n:12,lab:"far",film:1,title:"¿Cuántos agentes?",vis:{k:"role",ghost:1},
 sit:"La herramienta de gestión de servicios de TI lista 140 aplicaciones y ningún agente. Quien dirige el área de Tomás pregunta cuántos agentes trabajan hoy en la empresa.",
 opts:[{t:"Contar las aplicaciones que la herramienta marca como IA, ya que los proveedores ahora dicen lo que sus productos pueden hacer.",why:"La herramienta lista aplicaciones, no lo que está activado dentro de ellas: el chat llegó en una actualización del software del centro de contacto."},
  {t:"Buscar donde los agentes dejan rastros: notas de versión y contratos, registros de llamadas a modelos, y la respuesta de cada equipo.",ok:true},
  {t:"Pedirle a cada proveedor la lista de los agentes de sus productos, y poner cada uno en el mapa a medida que se confirma.",why:"Los proveedores solo conocen sus propios productos. El planificador de cuadrillas lo crearon los analistas de la red, y ningún proveedor lo listaría."}],
 why:"Los agentes se esconden dentro de las aplicaciones, así que Tomás buscó donde dejan rastros: notas de versión y contratos de proveedores, registros de llamadas a modelos de lenguaje, y la respuesta de cada equipo. Halló seis agentes y un ayudante, donde el mapa mostraba dos."},
{type:"choice",n:13,lab:"far",film:1,title:"Alguien en casa con soporte vital",vis:{k:"role",hand:1},
 sit:"Un hogar le pregunta al chat por su factura, y dice que alguien en casa necesita luz para un equipo médico.",
 opts:[{t:"El chat responde la pregunta sobre la factura, y luego deja una nota en la cuenta para que la lea un gestor.",why:"Su rol dice cuándo deriva el caso: quien mencione dificultades, una enfermedad o soporte vital pasa a una persona, el mismo día."},
  {t:"El chat pregunta qué equipo es, para que el gestor que devuelva la llamada tenga todo a mano.",why:"Eso es información médica, y el chat no tiene por qué recogerla. Una persona pregunta lo que necesita, una vez que comprobó con quién habla."},
  {t:"El chat pasa el hogar a una persona, el mismo día, y le avisa que una persona se pondrá en contacto.",ok:true}],
 why:"El rol de un agente dice cuándo deriva el caso, y a quién. Quien mencione dificultades, una enfermedad o soporte vital pasa a una persona, el mismo día, y el agente se lo dice."},
{type:"choice",n:21,lab:"platform",film:2,title:"Una clave propia",vis:{k:"gate",round:1},
 sit:"El nuevo agente de planificación de la red necesita un modelo. Su analista ya tiene la clave de un proveedor, y podría llamar al modelo directo esta misma tarde.",
 opts:[{t:"Llegar al modelo por la puerta de enlace, con la identidad propia del agente, como hacen todos los demás agentes.",ok:true},
  {t:"Usar la clave por ahora, y pasar a la puerta de enlace cuando los resultados del agente sean lo bastante buenos.",why:"Así se configuró el planificador de cuadrillas: cuando el proveedor retiró su modelo, nadie lo supo, y los turnos se pararon."},
  {t:"Usar la clave, y dibujar la llamada en el mapa, para que el equipo de la plataforma vea qué modelo usa.",why:"Dibujada o no, una llamada por fuera de la puerta de enlace no queda anotada ni dentro de límites, y puede llegar a un modelo sin condiciones."}],
 why:"Cada llamada a un modelo pasa por una sola puerta: con la identidad propia del agente, anotada, dentro de sus límites, y solo a modelos con los que la empresa tiene condiciones. Así, el próximo retiro encuentra a cada agente que afecta."},
{type:"choice",n:22,lab:"platform",film:2,title:"Lo que cuestan los agentes",vis:{k:"gate",log:1},
 sit:"Finanzas pregunta cuánto costaron el mes pasado los agentes de cada equipo.",
 opts:[{t:"Pedirle al responsable de cada agente que estime su parte de las facturas del mes pasado de los proveedores de modelos.",why:"Las facturas llegan por proveedor, no por agente, y una estimación es una suposición. Las llamadas ya están anotadas."},
  {t:"Repartir las facturas de los proveedores por partes iguales entre los equipos que usan agentes, ya que los contratos son compartidos.",why:"Un equipo cuyo agente se atascó en un bucle pagaría lo mismo que uno que casi no llamó a un modelo."},
  {t:"Leer el registro de la puerta de enlace, que anota cada llamada: qué agente, qué modelo, cuándo y cuánto costó.",ok:true}],
 why:"La puerta de enlace anota cada llamada, y cada mes su registro le muestra a cada equipo cuánto cuestan sus agentes."},
{type:"choice",n:23,lab:"platform",film:2,title:"Se retira un modelo",vis:{k:"gate",retire:1},
 sit:"Un proveedor avisa: un modelo al que llaman tres de los agentes se retirará en dos meses.",
 opts:[{t:"El responsable de cada agente lo pasa al modelo de reemplazo en cuanto recibe el aviso, para que nada se pare.",why:"Pasar sin probar antes el reemplazo con los controles del agente es la manera en que un turno, o una respuesta, sale mal sin que nadie lo vea."},
  {t:"El equipo de Ravi busca en el registro de la puerta de enlace qué agentes lo llaman, y prueba el reemplazo con sus controles.",ok:true},
  {t:"El equipo de Ravi pasa los tres agentes al reemplazo el mismo día del aviso, ya que es quien opera la plataforma.",why:"La plataforma es compartida, pero el responsable de cada agente responde por lo que hace, así que cada responsable revisa los resultados y acepta."}],
 why:"El registro de la puerta de enlace muestra qué agentes llaman al modelo. El equipo de Ravi prueba el reemplazo con los controles de cada agente, cada responsable revisa los resultados y acepta, y los tres pasan en una tarde."},
{type:"choice",n:31,lab:"place",film:3,title:"Su propio consumo",vis:{k:"place",hi:"consumo cada media hora",to:"sign-in",lv:"confidential"},
 sit:"Los hogares empiezan a preguntarle al chat por su propio consumo, media hora a media hora. Las lecturas de los medidores son un producto que lleva el equipo de Grace.",
 opts:[{t:"Poner el producto de lecturas en el lugar del chat, para que pueda responder a cualquiera que pregunte por el consumo.",why:"Las lecturas de un hogar son suyas, tan confidenciales como su cuenta. En el lugar del chat, cualquiera podría saber del consumo de cualquiera."},
  {t:"Leer las lecturas de un hogar solo cuando su titular inicia sesión, como el chat lee una cuenta.",ok:true},
  {t:"Enmascarar los números de cuenta en las lecturas, y luego poner el producto de lecturas en el lugar del chat.",why:"Una máscara deja los datos al alcance, y una regla equivocada los deja pasar. Y lo que consume un hogar todavía puede decir quién es."}],
 why:"El consumo, como una cuenta, es propio de cada hogar: el chat lo lee solo cuando su titular inicia sesión. Grace, responsable del producto, acepta en el ticket, como con todo lector nuevo."},
{type:"choice",n:32,lab:"place",film:3,title:"Precios nuevos hoy",vis:{k:"place",hi:"las tarifas de hoy",to:"in",at:0,lv:"public"},
 sit:"Hoy empiezan los precios nuevos. Esta tarde, un hogar le pregunta al chat cuánto pagará por una unidad de energía.",
 opts:[{t:"Da el precio de hoy: el producto de tarifas cambió esta mañana, y eso es lo que lee el chat.",ok:true},
  {t:"Da el precio del mes pasado, hasta que alguien actualice los precios escritos en sus instrucciones.",why:"Precios en sus instrucciones serían una copia, que nadie lleva. El chat lee el producto de tarifas, que cambia el día que cambian los precios."},
  {t:"Dice que los precios están cambiando, y le pide al hogar que llame, por si da uno viejo.",why:"No necesita adivinar: el producto de tarifas cambia ese día, y también su respuesta."}],
 why:"El chat lee los productos oficiales, al día por sus contratos: cuando cambian los precios, el producto de tarifas cambia ese día, y también la respuesta del chat."},
{type:"choice",n:33,lab:"place",film:3,title:"Una copia más rápida",vis:{k:"place",hi:"tarifas, copiadas a un archivo",to:"out",lv:"public"},
 sit:"Un ingeniero sugiere que el chat guarde su propia copia de las tarifas en un archivo, para responder un poco más rápido.",
 opts:[{t:"Guardar la copia, y actualizarla cada noche, para que el chat nunca esté más de un día atrasado con los precios.",why:"Los precios cambian en un día, no de noche: durante un día, los hogares oirían el precio viejo, como el que planeó su invierno con él."},
  {t:"Guardar la copia, y pedirle al equipo de tarifas que avise al ingeniero cada vez que cambien los precios.",why:"Es una copia de una copia con una sola persona para recordarla: la exportación de la carpeta compartida no la actualizaba nadie."},
  {t:"Seguir leyendo el producto de tarifas, que cambia el día que cambian los precios: una copia necesita quien la lleve.",ok:true}],
 why:"El chat lee del original: los productos oficiales, con contratos que dicen qué tan al día están y quién responde por ellos. Ni exportaciones, ni copias de copias."},
{type:"choice",n:41,lab:"confirm",film:4,title:"Diez semanas",vis:{k:"draft"},
 sit:"El gobierno pide el diseño de otro servicio nuevo en diez semanas. Los talleres de la tarifa nocturna duraron ocho meses.",
 opts:[{t:"Pedirle a cada equipo que primero escriba cómo trabaja, y hacer los talleres cuando ya esté todo por escrito.",why:"Eso es describirlo todo desde cero, y es lo que tardó ocho meses."},
  {t:"Comprarle a una consultora el diseño de referencia de una empresa de energía, y adoptarlo tal como viene.",why:"Los modelos de referencia son donde empieza un borrador, no la respuesta: solo lo que confirman los responsables de esta empresa pasa a ser el modelo."},
  {t:"Empezar los talleres desde un primer borrador, tomado de los modelos de la industria y de los documentos de la empresa.",ok:true}],
 why:"La gente responde mejor a una propuesta que a una pregunta abierta. Un primer borrador desde los modelos de referencia de la industria y los documentos propios de la empresa, cada elemento con su fuente, les da a los talleres algo a lo que reaccionar."},
{type:"choice",n:42,lab:"confirm",film:4,title:"Sin fuente",vis:{k:"draft",hi:2,guess:1},
 sit:"Una línea del borrador de la batería dice que la red decide cuándo se carga la batería. No da ninguna fuente.",
 opts:[{t:"Dejarla: el agente leyó los modelos de referencia de la industria, así que la línea muy probablemente está bien.",why:"Una fuente muestra de dónde viene una línea, y esta no tiene ninguna. Probable no es confirmado."},
  {t:"Tratarla como una suposición del propio agente, marcada como tal, para que la resuelva Grace, su responsable.",ok:true},
  {t:"Tacharla, ya que un elemento sin fuente no tiene lugar en un primer borrador.",why:"Donde ninguna fuente lo dice, el borrador lo dice, y el responsable lo resuelve. Tacharla pierde la pregunta que plantea."}],
 why:"Donde ninguna fuente lo dice, el borrador lo dice: la línea es una suposición del agente, marcada como tal. Grace, responsable de la parte de la red, la resuelve, y solo lo que ella confirma pasa a ser el modelo."},
{type:"choice",n:43,lab:"confirm",film:4,title:"Cada fuente tenía razón",vis:{k:"draft",hi:1,join:1},
 sit:"Un paso del borrador une dos fuentes, cada una correcta por sí sola: la lista de la red de casas con paneles solares, y la forma en que comercialización invita a sus clientes.",
 opts:[{t:"Preguntarle a Ama: un paso que une datos de la red y de comercialización puede cruzar el muro, sean cuales sean sus fuentes.",ok:true},
  {t:"Confirmar el paso tal como está: cada fuente detrás de él es correcta, y cada responsable ya revisó la suya.",why:"Cada fuente tenía razón por sí sola. El paso que las unió llevó información de clientes al otro lado del muro."},
  {t:"Pedirle al agente que vuelva a redactar el paso desde otras fuentes, hasta que nadie le encuentre ninguna falla.",why:"El error no estaba en las fuentes, sino en el paso. Eso lo encuentra un responsable, Ama por las reglas, y el agente vuelve a redactar desde su corrección."}],
 why:"Lo encontró Ama: la información de los clientes se queda donde se recogió, y la red debe tratar igual a todas las comercializadoras. Así que la red ofrece la batería a todas las comercializadoras en las mismas condiciones, y cada una invita a sus propios clientes."},
{type:"choice",n:51,lab:"checks",film:5,title:"En producción mañana",vis:{k:"checks",fail:0},
 sit:"Un informe nuevo falla una comprobación: lee una tabla que no tiene responsable. Su equipo lo quiere en producción mañana.",
 opts:[{t:"Apagar esa comprobación solo para este cambio, y volver a encenderla cuando el informe ya esté en producción.",why:"Una comprobación apagada para un cambio no para nada, y el próximo cambio puede apagarla también."},
  {t:"Espera hasta que la tabla tenga un responsable, o hasta que el responsable del cambio anote por qué sigue adelante.",ok:true},
  {t:"Dejarlo salir mañana, y pedirle a Tomás que después le busque un responsable a la tabla y la agregue al mapa.",why:"Entonces la comprobación no significa nada, y una tabla que nadie lleva tiene un lector más que nadie puede ver."}],
 why:"Un cambio que falla una comprobación espera, hasta corregirse o hasta que su responsable diga por qué. Una comprobación apagada deja pasar cualquier cosa."},
{type:"choice",n:52,lab:"checks",film:5,title:"Un modelo nuevo para el agente",vis:{k:"checks",agent:1,alt:"test"},
 sit:"La semana que viene, el agente del mapa pasa a un modelo más nuevo. Sus recorridos llevan meses saliendo bien.",
 opts:[{t:"Nada: pasó su prueba cuando empezó a trabajar, con los catorce elementos y los cinco responsables.",why:"Haber pasado entonces no dice nada de un modelo nuevo. La prueba se repite cada vez que cambian su modelo o sus instrucciones."},
  {t:"Mirar de cerca sus próximos recorridos, y compararlos uno a uno con lo que Tomás espera ver.",why:"Una prueba necesita una respuesta conocida, no la sensación de que un recorrido se ve bien."},
  {t:"Volver a correr primero su prueba con la tarifa social, cuya respuesta, catorce elementos, se conoce.",ok:true}],
 why:"Antes de que nadie confíe en sus recorridos, al agente se lo prueba con un cambio cuya respuesta se conoce, y la prueba se repite cada vez que cambian su modelo o sus instrucciones."},
{type:"choice",n:53,lab:"checks",film:5,title:"Un lector que nadie dibujó",vis:{k:"checks",estate:1,alt:"estate"},
 sit:"Al contrastar un recorrido con lo que está en marcha, el agente encuentra una tarea nocturna que copia los contactos de los clientes. No está en el mapa.",
 opts:[{t:"Informa lo que encontró, con su evidencia, y el responsable de los contactos decide qué pasa.",ok:true},
  {t:"Apaga la tarea, ya que nada que no esté en el mapa debería tocar los contactos de los clientes.",why:"Los agentes nunca cambian producción: ahí, un agente solo lee, encuentra y redacta. Una persona decide, y el cambio lo hace el despliegue."},
  {t:"Agrega la tarea al mapa por su cuenta, con el equipo de datos como responsable, para que las comprobaciones corran sobre ella.",why:"El agente redacta; un responsable confirma. Y el responsable de la tarea responde por los contactos, y ese no es el equipo de datos por omisión."}],
 why:"En producción, el agente lee en solo lectura, con los datos personales y sensibles enmascarados, y redacta lo que encuentra. El responsable decide, como hizo quien dirige comercialización con la copia del centro de contacto, y la copia entra en el mapa con un responsable."}
],
pics:{
 role:{title:"un agente en el mapa",role:"un rol propio",id:"una identidad propia",steps:["informar","redactar","verificar","ejecutar"],person:"una persona"},
 gate:{title:"una sola puerta a cada modelo",gateway:"la puerta de enlace",models:["modelo A","modelo B","modelo C"],log:["chat · modelo A · 09:14","planificador · modelo B · 09:15","agente del mapa · modelo A · 09:17"]},
 place:{title:"el lugar propio del chat",its:"solo lo que puede leer",inside:[["tarifas","public"],["trabajos programados","internal"],["páginas de ayuda","public"]],outside:[["necesidades médicas","restricted"],["cuentas","confidential"]]},
 draft:{title:"primer borrador · la batería",guess:"sin fuente: suposición",rows:[["Operar la batería","lista de la IEC","Grace"],["Invitar hogares","lista de la red + comercialización","comercialización"],["Decidir cuándo se carga","—","Grace"],["Acreditar cada factura","reglas de producto de comercialización","comercialización"]]},
 checks:{title:"las comprobaciones del mapa",agent:"la prueba propia del agente del mapa",test:"la tarifa social: 14 elementos, 5 responsables",model:"un modelo nuevo",rows:["un responsable y una fuente","realizada","representa un objeto de negocio","enlazado, y una sola vez","el caso de una regla debe fallar"],
  estate:"el mapa, y lo que de verdad está en marcha",map:"el mapa",running:"lo que está en marcha",table:"contactos",reader:"una tarea nocturna"},
 alt:{role:"Un agente en el mapa, en un rol propio con una identidad propia, y los cuatro pasos que puede dar en una tarea.",gate:"Seis agentes, la puerta de enlace por la que pasa cada llamada, y los modelos detrás de ella.",
  place:"El lugar propio del chat, con los productos que puede leer adentro, y lo que no puede leer afuera.",draft:"Un primer borrador en papel: cada elemento con su fuente, y el responsable que debe confirmarlo.",
  checks:"Las comprobaciones del mapa, cada una con sus últimas corridas.",test:"La prueba propia del agente del mapa con la tarifa social, aprobada en cada corrida hasta ahora, y la corrida que todavía necesita con su modelo nuevo.",
  estate:"El mapa junto a lo que de verdad está en marcha: la misma tabla de contactos, y una tarea nocturna que la lee y que el mapa nunca dibujó."}},
done:[["Todas las decisiones bien tomadas.","Pondrías cada agente en un rol propio, sobre una sola plataforma, leyendo solo lo que puede; empezarías desde un borrador que confirman los responsables; y comprobarías el mapa en cada cambio."],
 ["Casi todas.","Abre el lab junto a cada situación que te faltó: pone esa idea en tus manos."],
 ["Un buen comienzo.","Mira los capítulos detrás de los labs que te faltaron, y luego vuelve a probar esas situaciones."],
 ["Empieza por las películas.","Cada lab y cada situación vienen de una película: mírala, y luego prueba su lab."]]};
